import { useState, useEffect } from "react";
import { useFormik } from "formik";
import Toast from "../components/Toast";
import { useAuth } from "../context/AuthContext";

const API_URL = process.env.REACT_APP_API_URL || "http://localhost:5000/api";

// ── Validation function (used by Formik) ──────────────────────────────────────
function validate(values) {
  const errors = {};

  if (!values.name.trim()) {
    errors.name = "Product name is required";
  }

  if (!values.price) {
    errors.price = "Price is required";
  } else if (Number(values.price) < 0) {
    errors.price = "Price must be a positive number";
  }

  if (values.stock !== "" && Number(values.stock) < 0) {
    errors.stock = "Stock must be a positive number";
  }

  return errors;
}

// ── Component ─────────────────────────────────────────────────────────────────
function AdminProducts() {
  const { token } = useAuth();

  // State
  const [products, setProducts]      = useState([]);
  const [categories, setCategories]  = useState([]);
  const [loading, setLoading]        = useState(true);
  const [dialogOpen, setDialogOpen]  = useState(false);
  const [editingProduct, setEditing] = useState(null);
  const [deleteId, setDeleteId]      = useState(null);
  const [toast, setToast]            = useState(null);
  const [imagePreview, setPreview]   = useState(""); // local image preview

  // Load products and categories when page opens
  useEffect(() => {
    fetchProducts();
    fetchCategories();
  }, []);

  // ── Fetch all products from backend ────────────────────────────────────────
  const fetchProducts = async () => {
    setLoading(true);
    try {
      const res  = await fetch(`${API_URL}/products`);
      const data = await res.json();
      setProducts(data);
    } catch (err) {
      setToast({ message: "Could not load products", type: "error" });
    }
    setLoading(false);
  };

  // ── Fetch all categories from backend ──────────────────────────────────────
  const fetchCategories = async () => {
    try {
      const res  = await fetch(`${API_URL}/categories`);
      const data = await res.json();
      setCategories(data);
    } catch (err) {
      // silently fail
    }
  };

  // ── Open dialog to CREATE a new product ───────────────────────────────────
  const openCreate = () => {
    setEditing(null);
    setPreview("");
    formik.resetForm();
    setDialogOpen(true);
  };

  // ── Open dialog to EDIT an existing product ───────────────────────────────
  const openEdit = (product) => {
    setEditing(product);
    setPreview(product.image || ""); // show existing image in preview
    formik.setValues({
      name:        product.name        || "",
      description: product.description || "",
      price:       product.price       || "",
      stock:       product.stock       ?? "",
      material:    product.material    || "",
      category:    product.category?._id || product.category || "",
      image:       product.image       || "",
    });
    setDialogOpen(true);
  };

  // ── Handle image file selection ───────────────────────────────────────────
  // We convert the chosen file to a base64 string.
  // This way we can send it as a normal JSON string (req.body.image) — no backend changes needed.
  const handleImageChange = (e) => {
    const file = e.target.files[0];
    if (!file) return;

    const reader = new FileReader();

    // This runs when the file is finished being read
    reader.onloadend = () => {
      const base64String = reader.result; // looks like "data:image/png;base64,....."
      formik.setFieldValue("image", base64String); // save into Formik state
      setPreview(base64String);                    // show preview immediately
    };

    reader.readAsDataURL(file); // start reading the file as base64
  };

  // ── Formik setup ──────────────────────────────────────────────────────────
  const formik = useFormik({
    initialValues: {
      name:        "",
      description: "",
      price:       "",
      stock:       "",
      material:    "",
      category:    "",
      image:       "", // will hold the base64 string after user picks a file
    },
    validate,
    onSubmit: async (values, { setStatus, setSubmitting }) => {
      setStatus(null);
      try {
        // Decide URL and HTTP method based on create vs edit mode
        const url    = editingProduct
          ? `${API_URL}/products/${editingProduct._id}`
          : `${API_URL}/products`;
        const method = editingProduct ? "PUT" : "POST";

        const res = await fetch(url, {
          method,
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${token}`,
          },
          body: JSON.stringify({
            ...values,
            price: Number(values.price),
            stock: Number(values.stock) || 0,
            // values.image already contains the base64 string
          }),
        });

        if (!res.ok) {
          const data = await res.json();
          setStatus(data.message || "Something went wrong");
          return;
        }

        setToast({ message: editingProduct ? "Product updated!" : "Product created!", type: "success" });
        setDialogOpen(false);
        fetchProducts(); // refresh the product list
      } catch (err) {
        setStatus("Network error. Please try again.");
      } finally {
        setSubmitting(false);
      }
    },
  });

  // ── Delete a product ──────────────────────────────────────────────────────
  const handleDelete = async () => {
    try {
      const res = await fetch(`${API_URL}/products/${deleteId}`, {
        method: "DELETE",
        headers: { Authorization: `Bearer ${token}` },
      });
      if (!res.ok) throw new Error("Failed to delete product");
      setToast({ message: "Product deleted", type: "success" });
      fetchProducts();
    } catch (err) {
      setToast({ message: err.message, type: "error" });
    }
    setDeleteId(null);
  };

  // ── UI ────────────────────────────────────────────────────────────────────
  return (
    <div className="container py-4">

      {/* Header row */}
      <div className="d-flex justify-content-between align-items-center mb-4">
        <div>
          <h4 className="serif mb-0">Products</h4>
          <small className="text-muted">{products.length} total</small>
        </div>
        <button className="btn btn-dark" onClick={openCreate}>
          <i className="bi bi-plus me-1"></i> Add Product
        </button>
      </div>

      {/* ── Product Cards ── */}
      {loading ? (
        <div className="row g-3">
          {[1, 2, 3].map((n) => (
            <div key={n} className="col-12 col-sm-6 col-md-4">
              <div className="card placeholder-glow" style={{ height: 200 }}>
                <div className="placeholder w-100 h-100"></div>
              </div>
            </div>
          ))}
        </div>
      ) : (
        <div className="row g-3">
          {products.map((p) => (
            <div className="col-12 col-sm-6 col-md-4" key={p._id}>
              <div className="card h-100">

                {/* Product image */}
                <div style={{ height: 160, overflow: "hidden", background: "#f5f5f5" }}>
                  {p.image ? (
                    <img
                      src={p.image}
                      alt={p.name}
                      className="w-100 h-100"
                      style={{ objectFit: "cover" }}
                    />
                  ) : (
                    <div className="w-100 h-100 d-flex align-items-center justify-content-center text-muted">
                      <i className="bi bi-image fs-1"></i>
                    </div>
                  )}
                </div>

                {/* Product info */}
                <div className="card-body d-flex flex-column">
                  <h6 className="card-title mb-1">{p.name}</h6>
                  <p className="text-muted mb-2" style={{ fontSize: "0.85rem" }}>${p.price}</p>
                  <div className="d-flex justify-content-between align-items-center mt-auto">
                    <span className={`badge ${p.stock > 0 ? "bg-secondary" : "bg-dark"}`}>
                      Stock: {p.stock}
                    </span>
                    <div className="d-flex gap-2">
                      <button className="btn btn-sm btn-outline-secondary" onClick={() => openEdit(p)}>
                        <i className="bi bi-pencil"></i>
                      </button>
                      <button className="btn btn-sm btn-outline-danger" onClick={() => setDeleteId(p._id)}>
                        <i className="bi bi-trash"></i>
                      </button>
                    </div>
                  </div>
                </div>

              </div>
            </div>
          ))}

          {products.length === 0 && (
            <div className="col-12 text-center py-5 text-muted">No products yet.</div>
          )}
        </div>
      )}

      {/* ── Create / Edit Modal ── */}
      {dialogOpen && (
        <div
          className="modal show d-flex"
          style={{ background: "rgba(0,0,0,0.5)", position: "fixed", inset: 0, zIndex: 300, alignItems: "center", justifyContent: "center" }}
        >
          <div className="modal-dialog modal-dialog-scrollable w-100" style={{ maxWidth: 520 }}>
            <div className="modal-content">

              {/* Modal header */}
              <div className="modal-header">
                <h5 className="modal-title">{editingProduct ? "Edit Product" : "Add New Product"}</h5>
                <button type="button" className="btn-close" onClick={() => setDialogOpen(false)}></button>
              </div>

              {/* Modal body = the form */}
              <div className="modal-body">
                <form onSubmit={formik.handleSubmit} noValidate>

                  {/* Server-side error message */}
                  {formik.status && (
                    <div className="alert alert-danger py-2" style={{ fontSize: "0.83rem" }}>
                      {formik.status}
                    </div>
                  )}

                  {/* Name field */}
                  <div className="mb-3">
                    <label className="form-label">Product Name *</label>
                    <input
                      name="name"
                      className={`form-control ${formik.touched.name && formik.errors.name ? "is-invalid" : ""}`}
                      value={formik.values.name}
                      onChange={formik.handleChange}
                      onBlur={formik.handleBlur}
                    />
                    {/* Show error only after user touches the field */}
                    {formik.touched.name && formik.errors.name && (
                      <div className="invalid-feedback">{formik.errors.name}</div>
                    )}
                  </div>

                  {/* Description field */}
                  <div className="mb-3">
                    <label className="form-label">Description</label>
                    <textarea
                      name="description"
                      className="form-control"
                      rows={3}
                      value={formik.values.description}
                      onChange={formik.handleChange}
                    />
                  </div>

                  {/* Price and Stock side by side using Bootstrap grid */}
                  <div className="row g-3 mb-3">
                    <div className="col-6">
                      <label className="form-label">Price *</label>
                      <input
                        type="number"
                        name="price"
                        className={`form-control ${formik.touched.price && formik.errors.price ? "is-invalid" : ""}`}
                        value={formik.values.price}
                        onChange={formik.handleChange}
                        onBlur={formik.handleBlur}
                      />
                      {formik.touched.price && formik.errors.price && (
                        <div className="invalid-feedback">{formik.errors.price}</div>
                      )}
                    </div>
                    <div className="col-6">
                      <label className="form-label">Stock</label>
                      <input
                        type="number"
                        name="stock"
                        className={`form-control ${formik.touched.stock && formik.errors.stock ? "is-invalid" : ""}`}
                        value={formik.values.stock}
                        onChange={formik.handleChange}
                        onBlur={formik.handleBlur}
                      />
                      {formik.touched.stock && formik.errors.stock && (
                        <div className="invalid-feedback">{formik.errors.stock}</div>
                      )}
                    </div>
                  </div>

                  {/* Image upload field */}
                  <div className="mb-3">
                    <label className="form-label">Product Image</label>

                    {/* Preview: shows existing image (edit mode) or newly selected image */}
                    {imagePreview && (
                      <img
                        src={imagePreview}
                        alt="Preview"
                        className="d-block mb-2 rounded"
                        style={{ width: "100%", height: 160, objectFit: "cover" }}
                      />
                    )}

                    {/* File picker — user selects an image from their device */}
                    <input
                      type="file"
                      accept="image/*"
                      className="form-control"
                      onChange={handleImageChange}
                    />
                    <div className="form-text">Upload a JPG, PNG, or WEBP image.</div>
                  </div>

                  {/* Material field */}
                  <div className="mb-3">
                    <label className="form-label">Material</label>
                    <input
                      name="material"
                      className="form-control"
                      value={formik.values.material}
                      onChange={formik.handleChange}
                    />
                  </div>

                  {/* Category dropdown */}
                  <div className="mb-3">
                    <label className="form-label">Category</label>
                    <select
                      name="category"
                      className="form-select"
                      value={formik.values.category}
                      onChange={formik.handleChange}
                    >
                      <option value="">None</option>
                      {/* Map over categories array to create an option for each one */}
                      {categories.map((c) => (
                        <option key={c._id} value={c._id}>{c.name}</option>
                      ))}
                    </select>
                  </div>

                  {/* Form action buttons */}
                  <div className="modal-footer px-0 pb-0">
                    <button
                      type="button"
                      className="btn btn-outline-secondary"
                      onClick={() => setDialogOpen(false)}
                    >
                      Cancel
                    </button>
                    <button
                      type="submit"
                      className="btn btn-dark"
                      disabled={formik.isSubmitting}
                    >
                      {/* Show "Saving..." while the request is in progress */}
                      {formik.isSubmitting ? "Saving..." : editingProduct ? "Update" : "Create"}
                    </button>
                  </div>

                </form>
              </div>

            </div>
          </div>
        </div>
      )}

      {/* ── Delete Confirmation Modal ── */}
      {deleteId && (
        <div
          className="modal show d-flex"
          style={{ background: "rgba(0,0,0,0.5)", position: "fixed", inset: 0, zIndex: 300, alignItems: "center", justifyContent: "center" }}
        >
          <div className="modal-dialog">
            <div className="modal-content">
              <div className="modal-header">
                <h5 className="modal-title">Delete Product?</h5>
                <button className="btn-close" onClick={() => setDeleteId(null)}></button>
              </div>
              <div className="modal-body">
                <p className="text-muted mb-0">This action cannot be undone.</p>
              </div>
              <div className="modal-footer">
                <button className="btn btn-outline-secondary" onClick={() => setDeleteId(null)}>Cancel</button>
                <button className="btn btn-danger" onClick={handleDelete}>Delete</button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Toast notification */}
      {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}

    </div>
  );
}

export default AdminProducts;
